<!-- Article videos: the poster shows a large play button, so a click anywhere on a paused video starts it.
     The bottom 56px is left to the native control bar, whose own play button would otherwise toggle it straight back. -->
<script>
  document.addEventListener('click', function (e) {
    var v = e.target && e.target.closest ? e.target.closest('.article-body video, #article-body video') : null;
    if (!v || !v.paused) return;
    if (e.clientY > v.getBoundingClientRect().bottom - 56) return;
    e.preventDefault();
    v.play();
  }, true);
</script>

