// Freshdesk strips <button> elements and onclick attributes.
// We use <span class="copy-btn"> in the article HTML and a
// delegated listener here so no inline handlers are needed.
document.addEventListener('click', function(e) {
  var btn = e.target;
  if (!btn || !btn.classList || !btn.classList.contains('copy-btn')) return;
  var wrapper = btn.parentElement;
  var pre = wrapper ? wrapper.querySelector('pre') : null;
  if (!pre) return;
  var text = pre.innerText;
  navigator.clipboard.writeText(text.trim()).then(function() {
    var orig = btn.textContent;
    btn.textContent = 'Copied!';
    setTimeout(function() { btn.textContent = orig; }, 1500);
  }).catch(function() {
    var ta = document.createElement('textarea');
    ta.value = text.trim();
    document.body.appendChild(ta);
    ta.select();
    document.execCommand('copy');
    document.body.removeChild(ta);
    btn.textContent = 'Copied!';
    setTimeout(function() { btn.textContent = 'Copy'; }, 1500);
  });
});

// \xe2\x94\x80\xe2\x94\x80 Freshdesk heading anchors \xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80\xe2\x94\x80
// Freshdesk inserts <a class="copy-link-to-section"> as a
// sibling BEFORE each heading. This moves them inside the
// heading so the link icon renders inline with the heading text.
setTimeout(function() {
  document.querySelectorAll('.bd-api-docs a.copy-link-to-section').forEach(function(a) {
    var next = a.nextElementSibling;
    if (next && /^H[1-6]$/.test(next.tagName)) {
      next.insertBefore(a, next.firstChild);
    }
  });
}, 150);
</script>
<!-- END New API Documentation Articles -->

